<?php
declare(strict_types=1);
require dirname(__DIR__).'/includes/bootstrap.php';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&($_POST['action']??'')==='login'){
 csrf_check();$fingerprint=hash('sha256',($_SERVER['REMOTE_ADDR']??'local'));
 $failed=one('SELECT COUNT(*) n FROM login_attempts WHERE ip_hash=? AND attempted_at>DATE_SUB(NOW(), INTERVAL 15 MINUTE)',[$fingerprint]);
 if((int)$failed['n']>=8){$loginError='Too many attempts. Retry in 15 minutes.';}
 else{
  $username=trim((string)($_POST['username']??''));$pass=(string)($_POST['password']??'');
  $admin=one('SELECT id,username,password_hash FROM admins WHERE username=? AND active=1',[$username]);
  if($admin&&password_verify($pass,$admin['password_hash'])){
   session_regenerate_id(true);$_SESSION['admin_id']=(int)$admin['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));
   exec_sql('DELETE FROM login_attempts WHERE ip_hash=?',[$fingerprint]);exec_sql('UPDATE admins SET last_login=NOW() WHERE id=?',[$admin['id']]);header('Location: '.url('control/index.php'));exit;
  }
  exec_sql('INSERT INTO login_attempts(ip_hash) VALUES (?)',[$fingerprint]);$loginError='Incorrect username or password.';
 }
}
if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&($_POST['action']??'')==='logout'){
 csrf_check();$_SESSION=[];session_regenerate_id(true);header('Location: '.url('control/index.php'));exit;
}
$admin=admin_user();
if(!$admin):?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NOVA · Private login</title><link rel="stylesheet" href="<?=e(url('assets/css/admin.css'))?>"></head><body class="login-page"><div class="login-visual"><div class="login-shape">✳</div><span class="login-stamp">NOVA MARKET / PRIVATE SPACE</span><h1>One store.<br><em>Infinite possibilities.</em></h1><p>Products, sales, customers and performance — all in your hands.</p></div><div class="login-side"><form class="login-card" method="post"><div class="login-logo">✳ <strong>NOVA</strong> CONTROL</div><span class="kicker">AUTHORIZED PERSONNEL ONLY</span><h2>Welcome back.</h2><p>Sign in to your command center</p><?php if(!empty($loginError)):?><div class="alert alert-err"><?=e($loginError)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="login"><label>USERNAME<input name="username" autocomplete="username" required autofocus></label><label>PASSWORD<input type="password" name="password" autocomplete="current-password" required></label><button class="big-submit" type="submit">ACCESS DASHBOARD ↗</button><small>🔒 Encrypted session · Protected admin area</small></form></div></body></html><?php exit;endif;
$tab=(string)($_GET['tab']??'dashboard');$tabs=['dashboard','orders','products','categories','coupons','customers','analytics','notifications','settings','security','activity'];if(!in_array($tab,$tabs,true))$tab='dashboard';
$flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
$stats=one('SELECT COUNT(*) all_orders, COALESCE(SUM(CASE WHEN status<>"cancelled" THEN total ELSE 0 END),0) revenue, SUM(CASE WHEN status="new" THEN 1 ELSE 0 END) new_orders, SUM(CASE WHEN status="delivered" THEN 1 ELSE 0 END) delivered FROM orders')??[];
$vis=one('SELECT COUNT(*) unique_visitors, COALESCE(SUM(views),0) pageviews, SUM(CASE WHEN DATE(first_seen)=CURDATE() THEN 1 ELSE 0 END) today_visitors FROM visitors');
$catalog=one('SELECT COUNT(*) products, SUM(CASE WHEN stock<=5 AND id NOT IN (SELECT product_id FROM product_variants) THEN 1 ELSE 0 END) low_stock FROM products');
$cats=all('SELECT c.*, (SELECT COUNT(*) FROM products p WHERE p.category_id=c.id) product_count FROM categories c ORDER BY sort_order,id');
$products=all('SELECT p.*,c.name_fr cat_name,(SELECT COUNT(*) FROM product_variants v WHERE v.product_id=p.id) variant_count FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC');
$orders=all('SELECT * FROM orders ORDER BY id DESC LIMIT 250');
$orderItems=[];
if($tab==='orders' && $orders){
 $ids=array_map('intval',array_column($orders,'id'));
 $markers=implode(',',array_fill(0,count($ids),'?'));
 foreach(all('SELECT * FROM order_items WHERE order_id IN ('.$markers.') ORDER BY id',$ids) as $line)$orderItems[(int)$line['order_id']][]=$line;
}
$coupons=all('SELECT * FROM coupons ORDER BY id DESC');
$editProd=isset($_GET['edit'])?one('SELECT * FROM products WHERE id=?',[(int)$_GET['edit']]):null;
$editVars=$editProd?all('SELECT * FROM product_variants WHERE product_id=?',[$editProd['id']]):[];
$editGallery=$editProd?all('SELECT * FROM product_images WHERE product_id=?',[$editProd['id']]):[];
$editCat=isset($_GET['edit_cat'])?one('SELECT * FROM categories WHERE id=?',[(int)$_GET['edit_cat']]):null;
$editCoupon=isset($_GET['edit_coupon'])?one('SELECT * FROM coupons WHERE id=?',[(int)$_GET['edit_coupon']]):null;
$nav=[['dashboard','layout-dashboard','Overview'],['orders','shopping-bag','Orders'],['products','package','Products'],['categories','layers','Categories'],['coupons','tag','Coupons'],['customers','users','Customers'],['analytics','chart-no-axes-combined','Analytics'],['notifications','bell','Notifications'],['settings','settings','Store settings'],['security','shield-check','Security'],['activity','history','Activity log']];
function navurl(string $tab): string {return url('control/index.php?tab='.$tab);}
function fld(string $name,string $label,string $val='',string $type='text',string $extra=''):void {echo '<label class="field">'.e($label).'<input type="'.e($type).'" name="'.e($name).'" value="'.e($val).'" '.$extra.'></label>';}
function tog(string $key,string $label,string $val):void {echo '<label class="toggle-row"><span>'.e($label).'</span><input type="checkbox" name="'.e($key).'" value="1" '.($val==='1'?'checked':'').'></label>';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NOVA CONTROL · <?=e(ucfirst($tab))?></title><meta name="robots" content="noindex,nofollow"><link rel="stylesheet" href="<?=e(url('assets/css/admin.css'))?>"></head><body class="admin-page" data-tab="<?=e($tab)?>"><div class="admin-layout">
