<div class="admin-main"><header class="admin-header"><button class="admin-menu" id="adminMenu" aria-label="Menu">☰</button><div class="breadcrumbs">WORKSPACE <span>/</span> <b><?=e(strtoupper($tab))?></b></div><div class="admin-header-actions"><span class="live-dot"></span><span class="live-tag">STORE ONLINE</span><a href="<?=e(url('index.php'))?>" target="_blank" rel="noopener" class="view-store">↗ View Store</a><button id="enableNotifs" type="button" title="Enable browser alerts">♧ Alerts</button><span class="profile-circle"><?=e(strtoupper(substr($admin['username'],0,1)))?></span></div></header>
