ET: votre commande '.$o['order_number'].' est en cours de confirmation.')?>" rel="noopener" target="_blank" title="Message client">WhatsApp ↗</a></div><form method="post" action="<?=e(url('control/actions.php'))?>" class="status-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="order_status"><input type="hidden" name="order_id" value="<?=(int)$o['id']?>"><select name="status" aria-label="Order status" <?=$o['status']==='cancelled'?'disabled':''?>><?php foreach(['new','confirmed','preparing','shipped','delivered','cancelled'] as $s):?><option value="<?=$s?>" <?=$o['status']===$s?'selected':''?>><?=status_label($s)?></option><?php endforeach;?></select><button <?=$o['status']==='cancelled'?'disabled':''?>>Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
